// MK2 fonts as data URIs so they load from file:// too. Generated by tools/build_assets.py
(function () {
  const css = [];
  css.push("@font-face{font-family:'MK2';src:url(data:font/ttf;base64,) format('truetype');}");
  css.push("@font-face{font-family:'MKTitle';src:url(data:font/ttf;base64,) format('truetype');}");
  const s = document.createElement('style');
  s.textContent = css.join('\n');
  document.head.appendChild(s);
})();
